# Start the OPC UA server with the per-site dataset baked into the image.
# Environment variables:
#   SITE_NAME           — site name; /app/datasets/${SITE_NAME}.csv.gz is loaded
#   OPC_UA_PORT         — port to listen on (default 26543)
#   UPDATE_INTERVAL_MS  — data update interval in ms (default 5000)
#
# Datasets are generated by highbyte/generate_datasets.py (gzip-compressed,
# ~10x smaller than plain CSV) and COPYd into the image by the Dockerfile
# (Milwaukee, Detroit, CedarRapids). There is no runtime URL fetch.

if [ -n "$SITE_NAME" ] && [ -f "/app/datasets/${SITE_NAME}.csv.gz" ]; then
    echo "Using bundled dataset for site: $SITE_NAME"
    gunzip -c "/app/datasets/${SITE_NAME}.csv.gz" > dataset.csv
elif [ -n "$SITE_NAME" ] && [ -f "/app/datasets/${SITE_NAME}.csv" ]; then
    echo "Using bundled (uncompressed) dataset for site: $SITE_NAME"
    cp "/app/datasets/${SITE_NAME}.csv" dataset.csv
else
    echo "ERROR: SITE_NAME not set or /app/datasets/${SITE_NAME}.csv(.gz) missing — refusing to start"
    exit 1
fi

echo "Starting OPC UA server on port ${OPC_UA_PORT:-26543}..."
node server.mjs dataset.csv
